        zip.addView(space(8));zip.addView(txt("Substituição em lote",16,white,true));TextView helper=txt("Escolha uma textura e aplique a arquivos de imagem externos. Isso NÃO altera texturas embutidas dentro de .mdl.",12,muted,false);pad(helper,0,5,0,8);zip.addView(helper);
