        LinearLayout comp=row();LinearLayout before=col(),after=col();before.addView(txt("ORIGINAL DO PACK",9,muted,true));originalPackPreview=new ImageView(this);originalPackPreview.setScaleType(ImageView.ScaleType.FIT_CENTER);originalPackPreview.setBackground(bgd(Color.rgb(8,9,16),10));before.addView(originalPackPreview,lp(-1,100));Bitmap old=firstPreviewBitmap();if(old!=null)originalPackPreview.setImageBitmap(old);after.addView(txt("NOVA TEXTURA",9,cyan,true));replacementPreview=new ImageView(this);replacementPreview.setScaleType(ImageView.ScaleType.FIT_CENTER);replacementPreview.setBackground(bgd(Color.rgb(8,9,16),10));after.addView(replacementPreview,lp(-1,100));if(bulkReplacementBitmap!=null)replacementPreview.setImageBitmap(bulkReplacementBitmap);LinearLayout.LayoutParams half1=new LinearLayout.LayoutParams(0,-2,1);half1.rightMargin=dp(5);LinearLayout.LayoutParams half2=new LinearLayout.LayoutParams(0,-2,1);half2.leftMargin=dp(5);comp.addView(before,half1);comp.addView(after,half2);zip.addView(comp);
